  zh: { not_connected:'未连接', configure:'请在 /dashboard/api-settings 配置', success:'成功', error:'发生错误', completed:'已完成', db_not_configured:'数据库未配置', habit_name_required:'需要习惯名称', no_updates:'没有提供更新' }
};
