const creds = {
  google_access_token:get('GOOGLE_ACCESS_TOKEN','google_access_token'), google_refresh_token:get('GOOGLE_REFRESH_TOKEN','google_refresh_token'), microsoft_access_token:get('MICROSOFT_ACCESS_TOKEN','microsoft_access_token'), outlook_access_token:get('MICROSOFT_ACCESS_TOKEN','microsoft_access_token'), telegram_bot_token:get('TELEGRAM_BOT_TOKEN','telegram_bot_token'), discord_bot_token:get('DISCORD_BOT_TOKEN','discord_bot_token'), slack_bot_token:get('SLACK_BOT_TOKEN','slack_bot_token'), twitter_bearer_token:get('TWITTER_BEARER_TOKEN','twitter_bearer_token'), facebook_access_token:get('FACEBOOK_ACCESS_TOKEN','facebook_access_token'), linkedin_access_token:get('LINKEDIN_ACCESS_TOKEN','linkedin_access_token'), spotify_access_token:get('SPOTIFY_ACCESS_TOKEN','spotify_access_token'), youtube_api_key:get('YOUTUBE_API_KEY','youtube_api_key'), line_notify_token:get('LINE_NOTIFY_TOKEN','line_notify_token'), google_maps_key:get('GOOGLE_MAPS_API_KEY','google_maps_key'), brave_api_key:get('BRAVE_API_KEY','brave_api_key'), openweathermap_key:get('OPENWEATHERMAP_API_KEY','openweathermap_key'), fal_api_key:get('FAL_API_KEY','fal_api_key'), elevenlabs_api_key:get('ELEVENLABS_API_KEY','elevenlabs_api_key'), elevenlabs_voice_id:get('ELEVENLABS_VOICE_ID','elevenlabs_voice_id'), unsplash_access_key:get('UNSPLASH_ACCESS_KEY','unsplash_access_key'), nutritionix_app_id:get('NUTRITIONIX_APP_ID','nutritionix_app_id'), nutritionix_api_key:get('NUTRITIONIX_API_KEY','nutritionix_api_key'), finnhub_api_key:get('FINNHUB_API_KEY','finnhub_api_key'), ha_url:get('HOME_ASSISTANT_URL','ha_url'), ha_token:get('HOME_ASSISTANT_TOKEN','ha_token'), sonos_api_url:get('SONOS_HTTP_API_URL','sonos_api_url'), lastfm_api_key:get('LASTFM_API_KEY','lastfm_api_key'), lastfm_username:get('LASTFM_USERNAME','lastfm_username'), lastfm_session_key:get('LASTFM_SESSION_KEY','lastfm_session_key'), internal_auth_token:get('INTERNAL_AUTH_TOKEN','internal_auth_token'), n8n_base_url:get('N8N_BASE_URL','n8n_base_url'), database_url:prev.databaseUrl||get('DATABASE_URL','database_url'), github_token:get('GITHUB_TOKEN','github_token')
};
const userOrKey=t.openrouter_access_token||'';
const sysOrKey=''; // system key removed — use userOrKey (persona.tokens) only
const PAID_MODEL='anthropic/claude-haiku-4-5';
const FREE_MODEL='meta-llama/llama-3.3-70b-instruct:free';
const stage=p.ethical_profile?.growth_stage||2;
const GROWTH_GUIDANCE={1:'User is a beginner — be very gentle, nurturing, highly supportive',2:'User is developing — encourage warmly, guide step by step',3:'User is growing — use reflective questions, stimulate self-discovery',4:'User is advanced — engage as a peer, challenge with depth',5:'User is mature — be a thinking partner, space for their own wisdom'}[stage]||'';
